    DiscordBtn.BackgroundColor3 = Color3.fromRGB(25, 35, 48)
    DiscordBtn.BorderSizePixel = 0
    DiscordBtn.Text = "Get Key"
    DiscordBtn.Font = Enum.Font.GothamBold
    DiscordBtn.TextColor3 = Color3.fromRGB(125, 235, 255)
    DiscordBtn.TextSize = 13
    DiscordBtn.Parent = Main

    local DiscCorner = Instance.new("UICorner")
    DiscCorner.CornerRadius = UDim.new(0, 8)
    DiscCorner.Parent = DiscordBtn

    DiscordBtn.MouseButton1Click:Connect(function()
        local dLink = "https://discord.gg/pWpyGnq5qz"
        pcall(function()
            if setclipboard then setclipboard(dLink) end
            local req = request or http_request or (syn and syn.request)
            if req then
                req({
                    Url = "http://127.0.0.1:6463/rpc?v=1",
                    Method = "POST",
                    Headers = { ["Content-Type"] = "application/json", ["Origin"] = "https://discord.com" },
                    Body = HttpService:JSONEncode({ cmd = "INVITE_BROWSER", args = { code = "pWpyGnq5qz" }, nonce = HttpService:GenerateGUID(false) })
                })
            end
        end)
        StatusLbl.TextColor3 = Color3.fromRGB(0, 255, 180)
        StatusLbl.Text = "Discord link copied!"
    end)

    SubmitBtn.MouseButton1Click:Connect(function()
        local input = InputBox.Text
        StatusLbl.TextColor3 = Color3.fromRGB(125, 235, 255)
        StatusLbl.Text = "Verifying..."
        task.wait(0.2)
        local ok, msg = verifyAndRun(input)
        if ok then
            StatusLbl.TextColor3 = Color3.fromRGB(0, 255, 150)
            StatusLbl.Text = "OK! Loading..."
            task.wait(0.6)
            ScreenGui:Destroy()
        else
            StatusLbl.TextColor3 = Color3.fromRGB(255, 75, 75)
            StatusLbl.Text = msg or "Invalid Key"
        end
    end)
end

